        // Broadcast tau and the reflector v (held in lane k's colreg) to all
        // lanes via shuffle. v[k]==1 implicit; for r>k, v[r]==lane-k's colreg[r].
        tau_k = __shfl_sync(FULL, tau_k, k);
        float vbc[NMAX];
        #pragma unroll
        for (int r = 0; r < NMAX; ++r)
            vbc[r] = __shfl_sync(FULL, colreg[r], k);

        if (tau_k != 0.0f && lane > k && lane < n) {
            // apply H_k to this lane's column c (>k): w = v . col; col -= tau*v*w
            float w = colreg[k];                    // v[k]==1 * col[k]
            #pragma unroll
            for (int r = 0; r < NMAX; ++r)
                if (r > k && r < n) w += vbc[r] * colreg[r];
            float tw = tau_k * w;
            colreg[k] -= tw;                        // v[k]=1
            #pragma unroll
            for (int r = 0; r < NMAX; ++r)
                if (r > k && r < n) colreg[r] -= vbc[r] * tw;
        }
    }

    // Write H back: lane c writes column c. colreg now holds the final column
    // (R above+on diag from the applies and the lane==c diagonal write, the
    // reflector below from the lane==c step).
    if (lane < n) {
        #pragma unroll
        for (int r = 0; r < NMAX; ++r)
            if (r < n) Hb[(long)r * n + lane] = colreg[r];
    }
}

